def legacy_heating(up, down, data, cp, simple=False):
    """Reproduce m_fluxes.cc/fluxes.cc boundary quirks only for old references."""
    p = data["pressure"]
    net = up - down
    dfdp = np.empty_like(net)
    # ARTS2 used a secant across neighbors, not a nonuniform 3-point derivative.
    dfdp[1:-1] = (net[2:] - net[:-2]) / (p[2:] - p[:-2])
    # Original lower stencil accidentally takes upward flux from level 0.
    dfdp[0] = (-3 * net[0] + 4 * net[1] - (-down[2] + up[0])) / (p[2] - p[0])
    dfdp[-1] = (3 * net[-1] - 4 * net[-2] + net[-3]) / (p[-1] - p[-3])
    if simple:
        gravity = 9.80665
    else:
        # Original g0Earth at the default latitude 0, including its additional
        # centrifugal subtraction. Do not substitute the ARTS3 Earth model.
        gravity = (9.780327 - 0.033895) * (
            6378100.0 / (6378100.0 + data["altitude"])
        ) ** 2
        dfdp[-1] = 0  # Original varying-gravity loop skipped the last level.
    return hr.from_flux_divergence(dfdp, cp, gravity)


def solver(tau, source, surface, space, vector=False):
    n = len(tau) - 1
    if vector:
        positive = np.zeros((2, 1, 3, 4))
        negative = positive.copy()
        positive[0, 0, :, 0] = surface
        negative[0, 0, :, 0] = space
        emission = np.zeros(source.shape + (4,))
        emission[..., 0] = source
        return arts.cppvdisort(
            tau[1:],
            np.zeros(n),
            6,
            np.zeros((2, 1, n, 6, 6, 4, 4)),
            0.0,
            np.zeros(4),
            0.0,
            NFourier=1,
            b_pos=positive,
            b_neg=negative,
            s_poly_coeffs=emission,
        )
    return arts.cppdisort(
        tau[1:],
        np.zeros(n),
        6,
        np.ones((n, 1)),
        0.0,
        0.0,
        0.0,
        NLeg=1,
        NFourier=1,
        b_pos=np.full((1, 3), surface),
        b_neg=np.full((1, 3), space),
        s_poly_coeffs=source,
    )


def optical_depth(z, k):
    return np.r_[0, np.cumsum(-np.diff(z) * (k[1:] + k[:-1]) / 2)]


def test_radiance():
    field = arts.AtmField()
    field.extendxml("planets/Earth/Garand/garand_profile.0.xml")
    field["O2"] = 0.2095
    field["N2"] = 0.7808
    # CO2 is already present in the converted profile. The frozen extinction
    # below retains the original test's species/dilution treatment; these
    # constants are not used to regenerate absorption in this RT regression.
    data = EXTINCTION["TestHeatingRates"].copy()
    data["altitude"] = np.asarray(field["t"].data.grids[0])
    data["pressure"] = np.array([field["p"](z, 0.0, 0.0) for z in data["altitude"]])
    frequency = np.linspace(3e11, 3e13, 10)
    nodes, weights = np.polynomial.legendre.leggauss(3)
    mu = (nodes[::-1] + 1) / 2
    data["zenith"] = np.rad2deg(np.arccos(np.r_[mu, -mu[::-1]]))
    data["zenith_weights"] = np.r_[weights[::-1], weights] / 2
    radiance = np.zeros((len(frequency), len(data["pressure"]), 6))
    for angle in range(3):
        # The original 10-km maximum ray step produces a different vertical
        # subdivision for each zenith quadrature node. Absorption is sampled
        # at those points from the original LUT, rather than interpolated k.
        maximum_dz = 1e4 * mu[angle]
        altitude = data["altitude"]
        z = np.concatenate(
            [
                np.linspace(lo, hi, int(np.ceil((hi - lo) / maximum_dz)) + 1)[:-1]
                for lo, hi in zip(altitude[:-1], altitude[1:])
            ]
            + [[altitude[-1]]]
        )[::-1]
        t = np.array([field["t"](alt, 0.0, 0.0) for alt in z])
        k = data[f"k{angle}"][:, ::-1]
        levels = np.array([np.argmin(abs(z - v)) for v in data["altitude"]])
        for j, f in enumerate(frequency):
            tau = optical_depth(z, k[j])
            b = np.array([arts.physics.planck(f, temp) for temp in t])
            # ARTS2 first-order emission averages endpoint Planck radiances.
            dis = solver(
                tau,
                ((b[1:] + b[:-1]) / 2)[:, None],
                b[-1],
                arts.physics.planck(f, 2.72548),
            )
            u = np.asarray(dis.u(tau, [0]))[:, 0, :]
            # DISORT propagation cosines -> ARTS viewing zenith angles.
            radiance[j, :, angle] = u[levels, 5 - angle]
            radiance[j, :, 5 - angle] = u[levels, 2 - angle]

    # Exercise both orders of the original spectral/angular integration test.
    spectral_up, spectral_down = hr.flux_from_radiance(
        radiance, data["zenith"], data["zenith_weights"]
    )
    up, down = (
        hr.integrate_spectral(x, frequency) for x in (spectral_up, spectral_down)
    )
    broadband = hr.integrate_spectral(radiance, frequency)
    up2, down2 = hr.flux_from_radiance(
        broadband, data["zenith"], data["zenith_weights"]
    )
    heating = legacy_heating(up, down, data, 1006.0)
    np.testing.assert_allclose(
        heating, legacy_heating(up2, down2, data, 1006.0), rtol=0, atol=1e-14
    )
    np.testing.assert_allclose(
        heating,
        REFERENCE_HEATING["TestHeatingRates.heating_rates"],
        rtol=0,
        atol=1e-9,
    )


def test_disort(vector):
    data = EXTINCTION["Test_HeatingRate"].copy()
    data["frequency"] = np.linspace(3e11, 3e13, 10)
    data["pressure"] = np.geomspace(1013e2, 1.0, 81)
    # AFGL extends to 120 km; retain the original test's pressure range and
    # interpolate both altitude and temperature in log pressure as ARTS2 did.
    raw_p = arts.GriddedField3.fromxml("planets/Earth/afgl/tropical/p.xml")
    raw_t = arts.GriddedField3.fromxml("planets/Earth/afgl/tropical/t.xml")
    np.testing.assert_array_equal(raw_p.grids[0], raw_t.grids[0])
    log_pressure = np.log(np.asarray(raw_p.data).ravel()[::-1])
    for key, values in (
        ("altitude", np.asarray(raw_p.grids[0])),
        ("temperature", np.asarray(raw_t.data).ravel()),
    ):
        data[key] = np.interp(np.log(data["pressure"]), log_pressure, values[::-1])
    z, t = data["altitude"][::-1], data["temperature"][::-1]
    k = data["extinction"][:, ::-1]
    fluxes = []
    for j, f in enumerate(data["frequency"]):
        tau = optical_depth(z, k[j])
        b = np.array([arts.physics.planck(f, temp) for temp in t])
        # CDISORT suppresses its linear thermal source for dtau <= 1e-4,
        # retaining the top-of-layer Planck value. Preserve that input rule.
        slope = np.where(np.diff(tau) > 1e-4, np.diff(b) / np.diff(tau), 0.0)
        source = np.c_[b[:-1] - slope * tau[:-1], slope]
        dis = solver(tau, source, b[-1], arts.physics.planck(f, 2.72548), vector)
        # Request ALL levels explicitly: DisortFlux's gridded output omits TOA.
        fluxes.append(np.asarray(dis.flux(tau))[:, ::-1].copy())
    up, diffuse, direct, _ = hr.integrate_spectral(fluxes, data["frequency"])
    for simple, suffix in [(False, ""), (True, "_simple")]:
        heating = legacy_heating(up, diffuse + direct, data, 1003.5, simple)
        if not simple:
            assert heating[-1] == 0
        np.testing.assert_allclose(
            heating,
            REFERENCE_HEATING[f"Test_HeatingRate.heating_rates{suffix}"],
            rtol=0,
            atol=1e-6,
        )


test_radiance()
test_disort(False)
test_disort(True)
